import { Locator, Page, expect } from '@playwright/test';
import BasePage from '../Framework/src/pages/base.page';
import { HTMLSubStepLogger } from '../Framework/src/utils/htmlSubStepLogger';

export const DASHBOARD_METRIC_CARD_LABELS = [
  'Total Ranches',
  'Active Bookings',
  'Ranch Admins',
  'Total Guides',
  'This Month Revenue',
  'Pending Waivers',
] as const;

export const RECENT_BOOKINGS_TABLE_COLUMNS = [
  'Guest Name',
  'Ranch',
  'Dates',
  'Guide',
  'Hunters',
  'Guests',
  'Type',
  'Status',
] as const;

export const ACTIVE_RANCHES_TABLE_COLUMNS = ['Ranch Name', 'Location', 'Admin', 'Bookings'] as const;

export class DashboardPage extends BasePage {
  constructor(page: Page, subStepLogger?: HTMLSubStepLogger) {
    super(page, subStepLogger);
  }

  // ==================== Locators ====================

  get pageHeading(): Locator {
    return this.page.getByRole('heading', { name: 'Dashboard' });
  }

  get newBookingButton(): Locator {
    return this.page.getByRole('button', { name: 'New Booking' });
  }

  // --- Summary Metric Cards ---

  metricCard(label: (typeof DASHBOARD_METRIC_CARD_LABELS)[number]): Locator {
    return this.page.getByRole('heading', { name: label, exact: true }).locator('..');
  }

  metricCardValue(label: (typeof DASHBOARD_METRIC_CARD_LABELS)[number]): Locator {
    return this.metricCard(label).locator('text=/.+/').first();
  }

  // --- Tag Allocations ---

  get tagAllocationsPanel(): Locator {
    return this.page.getByRole('heading', { name: 'Tag Allocations' }).locator('..');
  }

  get tagAllocationsLoadingText(): Locator {
    return this.page.getByText('Loading tag allocations...');
  }

  get tagAllocationCards(): Locator {
    return this.tagAllocationsPanel.getByRole('group');
  }

  get tagAllocationsNextSlideButton(): Locator {
    return this.page.getByRole('button', { name: 'Next slide' });
  }

  get tagAllocationsPrevSlideButton(): Locator {
    return this.page.getByRole('button', { name: 'Previous slide' });
  }

  // --- Booking Calendar ---

  get bookingCalendarPanel(): Locator {
    return this.page.getByRole('heading', { name: 'Booking Calendar' }).locator('..');
  }

  get ranchFilterCombobox(): Locator {
    return this.bookingCalendarPanel.getByRole('combobox');
  }

  get calendarTodayButton(): Locator {
    return this.page.getByRole('button', { name: 'today' });
  }

  get calendarPrevMonthButton(): Locator {
    return this.page.getByRole('button', { name: 'Previous month' });
  }

  get calendarNextMonthButton(): Locator {
    return this.page.getByRole('button', { name: 'Next month' });
  }

  get calendarMonthHeading(): Locator {
    return this.bookingCalendarPanel.getByRole('heading', { level: 2 });
  }

  calendarViewToggle(view: 'Month' | 'Week' | 'Day' | 'Agenda'): Locator {
    return this.page.getByRole('button', { name: view });
  }

  get calendarGrid(): Locator {
    return this.page.getByRole('grid');
  }

  calendarDayCell(dateAccessibleName: string): Locator {
    return this.calendarGrid.getByRole('gridcell', { name: dateAccessibleName });
  }

  get bookingTypeLegend(): Locator {
    return this.page.getByText('Booking type').locator('..');
  }

  // --- Recent Bookings ---

  get recentBookingsPanel(): Locator {
    return this.page.getByRole('heading', { name: 'Recent Bookings' }).locator('..');
  }

  get recentBookingsViewAllButton(): Locator {
    return this.recentBookingsPanel.getByRole('button', { name: 'View All' });
  }

  get recentBookingsTable(): Locator {
    return this.recentBookingsPanel.getByRole('table');
  }

  get recentBookingsColumnHeaders(): Locator {
    return this.recentBookingsTable.getByRole('columnheader');
  }

  recentBookingsRow(guestOrBookingText: string): Locator {
    return this.recentBookingsTable.getByRole('row').filter({ hasText: guestOrBookingText });
  }

  // --- Active Ranches ---

  get activeRanchesPanel(): Locator {
    return this.page.getByRole('heading', { name: 'Active Ranches' }).locator('..');
  }

  get activeRanchesViewAllButton(): Locator {
    return this.activeRanchesPanel.getByRole('button', { name: 'View All' });
  }

  get activeRanchesTable(): Locator {
    return this.activeRanchesPanel.getByRole('table');
  }

  get activeRanchesColumnHeaders(): Locator {
    return this.activeRanchesTable.getByRole('columnheader');
  }

  activeRanchesRow(ranchName: string): Locator {
    return this.activeRanchesTable.getByRole('row').filter({ hasText: ranchName });
  }

  // ==================== Validations ====================

  async assertDashboardLoaded(): Promise<void> {
    await expect(this.page).toHaveURL(/\/dashboard/);
    await expect(this.pageHeading).toBeVisible();
    await expect(this.bookingCalendarPanel).toBeVisible();
    await expect(this.recentBookingsPanel).toBeVisible();
    await expect(this.activeRanchesPanel).toBeVisible();
    for (const label of DASHBOARD_METRIC_CARD_LABELS) {
      await expect(this.metricCard(label)).toBeVisible();
    }
  }

  async assertMetricCardValue(label: (typeof DASHBOARD_METRIC_CARD_LABELS)[number], expectedValue: string): Promise<void> {
    await expect(this.metricCard(label)).toContainText(expectedValue);
  }

  async assertAllMetricCardsZero(): Promise<void> {
    for (const label of DASHBOARD_METRIC_CARD_LABELS) {
      await expect(this.metricCard(label)).toContainText(/\$?0\b/);
    }
  }

  async assertTagAllocationsLoaded(): Promise<void> {
    await expect(this.tagAllocationsLoadingText).toBeHidden();
    await expect(this.tagAllocationCards.first()).toBeVisible();
  }

  async assertBookingEventOnDate(dateAccessibleName: string, eventText: string): Promise<void> {
    await expect(this.calendarDayCell(dateAccessibleName)).toContainText(eventText);
  }

  async assertCalendarMonthLabel(expectedMonthLabel: string): Promise<void> {
    await expect(this.calendarMonthHeading).toHaveText(expectedMonthLabel);
  }

  /** Asserts the REAL live table columns — see file-level discrepancy note. */
  async assertRecentBookingsTableHeaders(): Promise<void> {
    await expect(this.recentBookingsColumnHeaders).toHaveText([...RECENT_BOOKINGS_TABLE_COLUMNS]);
  }

  async assertRecentBookingContains(guestOrBookingText: string): Promise<void> {
    await expect(this.recentBookingsRow(guestOrBookingText)).toBeVisible();
  }

  async assertRecentBookingAbsent(guestOrBookingText: string): Promise<void> {
    await expect(this.recentBookingsRow(guestOrBookingText)).toHaveCount(0);
  }

  async assertActiveRanchesTableHeaders(): Promise<void> {
    await expect(this.activeRanchesColumnHeaders).toHaveText([...ACTIVE_RANCHES_TABLE_COLUMNS]);
  }

  async assertActiveRanchListed(ranchName: string): Promise<void> {
    await expect(this.activeRanchesRow(ranchName)).toBeVisible();
  }

  async assertNoHorizontalOverflow(): Promise<void> {
    const hasOverflow = await this.page.evaluate(
      () => document.documentElement.scrollWidth > document.documentElement.clientWidth,
    );
    expect(hasOverflow).toBe(false);
  }

  // ==================== Actions ====================

  async navigateToDashboard(): Promise<void> {
    await this.withHeal(this.page.getByRole('link', { name: 'Dashboard' }), (l) => l.click(), 'Dashboard Nav Link');
    await this.waitForLoadingToComplete();
  }

  async clickNewBooking(): Promise<void> {
    await this.withHeal(this.newBookingButton, (l) => l.click(), 'New Booking Button');
  }

  async filterCalendarByRanch(ranchName: string): Promise<void> {
    await this.withHeal(this.ranchFilterCombobox, (l) => l.selectOption({ label: ranchName }), 'Ranch Filter Combobox');
  }

  async goToNextMonth(): Promise<void> {
    await this.withHeal(this.calendarNextMonthButton, (l) => l.click(), 'Calendar Next Month Button');
  }

  async goToPreviousMonth(): Promise<void> {
    await this.withHeal(this.calendarPrevMonthButton, (l) => l.click(), 'Calendar Previous Month Button');
  }

  async switchCalendarView(view: 'Month' | 'Week' | 'Day' | 'Agenda'): Promise<void> {
    await this.withHeal(this.calendarViewToggle(view), (l) => l.click(), `Calendar ${view} View Toggle`);
  }

  async clickCalendarDay(dateAccessibleName: string): Promise<void> {
    await this.withHeal(this.calendarDayCell(dateAccessibleName), (l) => l.click(), `Calendar Day Cell: ${dateAccessibleName}`);
  }

  async clickRecentBookingsViewAll(): Promise<void> {
    await this.withHeal(this.recentBookingsViewAllButton, (l) => l.click(), 'Recent Bookings View All Button');
  }

  async clickActiveRanchesViewAll(): Promise<void> {
    await this.withHeal(this.activeRanchesViewAllButton, (l) => l.click(), 'Active Ranches View All Button');
  }

  async clickRecentBookingRow(guestOrBookingText: string): Promise<void> {
    await this.withHeal(this.recentBookingsRow(guestOrBookingText), (l) => l.click(), `Recent Booking Row: ${guestOrBookingText}`);
  }

  async clickActiveRanchRow(ranchName: string): Promise<void> {
    await this.withHeal(this.activeRanchesRow(ranchName), (l) => l.click(), `Active Ranch Row: ${ranchName}`);
  }

  async setViewport(width: number, height: number): Promise<void> {
    await this.page.setViewportSize({ width, height });
  }
}
